package postgres

// Shared readiness predicates keep event dispatch aligned with fenced claims.
const liveWakeCandidate = `SELECT c.id FROM recording_captures c JOIN recording_live l ON l.capture_id=c.id WHERE c.state IN ('uploading','freezing','validating','ready') AND c.terminal_at IS NULL AND NOT (` + capturePackageTerminal + `) AND c.expires_at>clock_timestamp() AND l.next_attempt_at<=clock_timestamp() AND (l.claimed_until IS NULL OR l.claimed_until<=clock_timestamp()) AND (l.revision>l.published_revision OR (NOT l.ended AND c.package_id IS NOT NULL AND jsonb_array_length(c.inventory->'renditions')=3 AND jsonb_array_length(l.segments)>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c.inventory->'renditions') r WHERE (r->>'segmentCount')::int<>jsonb_array_length(l.segments))) OR (NOT l.ended AND jsonb_array_length(l.segments)<4320 AND (SELECT count(*) FROM recording_capture_objects o WHERE o.capture_id=c.id AND o.state IN ('queued','verified') AND (o.path IN ('1080p/init.mp4','720p/init.mp4','480p/init.mp4') OR o.path IN ('1080p/seg-'||lpad(jsonb_array_length(l.segments)::text,6,'0')||'.m4s','720p/seg-'||lpad(jsonb_array_length(l.segments)::text,6,'0')||'.m4s','480p/seg-'||lpad(jsonb_array_length(l.segments)::text,6,'0')||'.m4s')))=6)) ORDER BY c.created_at LIMIT 1`

const sourceWakeCandidate = `SELECT id FROM recording_sources WHERE state IN ('finalizing','queued','processing') AND processing_attempts<3 AND retry_until>clock_timestamp() AND (claimed_until IS NULL OR claimed_until<=clock_timestamp()) ORDER BY created_at`

const packageWakeCandidate = `SELECT id FROM recording_packages WHERE state IN ('freezing','validating') AND validation_attempts<3 AND next_attempt_at<=clock_timestamp() AND (claimed_until IS NULL OR claimed_until<=clock_timestamp()) ORDER BY created_at`

const liveCoverWakeCandidate = `SELECT ` + liveCoverColumns + ` FROM recording_live_covers c WHERE (kind='custom' OR (` + previewWorkWaiting + `)) AND state IN ('pending','processing') AND attempts<3 AND next_attempt_at<=now() AND (claimed_until IS NULL OR claimed_until<=now()) AND created_at>now()-interval '24 hours' AND ` + liveCoverAlive + ` AND (kind='custom' OR EXISTS(SELECT 1 FROM recording_live l LEFT JOIN recording_broadcast_ranges b ON b.capture_id=l.capture_id WHERE l.capture_id=c.scope AND l.published_sequence>=COALESCE(b.start_sequence,0) AND (b.capture_id IS NULL OR b.start_sequence IS NOT NULL AND NOT b.revoked))) ORDER BY created_at`

const coverWakeCandidate = `SELECT ` + coverColumns + ` FROM recording_covers c JOIN recording_packages p ON p.id=c.package_id WHERE c.state IN ('pending','processing') AND c.attempts<3 AND c.next_attempt_at<=now() AND (c.claimed_until IS NULL OR c.claimed_until<=now()) AND c.expires_at>now() AND p.state='ready' AND p.media_expires_at>now()
AND (c.kind NOT IN ('auto','live-auto') OR p.broadcast_epoch=0 OR EXISTS (
 SELECT 1 FROM recording_broadcast_ranges b JOIN recording_live l ON l.capture_id=b.capture_id
 WHERE b.capture_id=p.id AND b.recording_id=p.recording_id AND b.epoch=p.broadcast_epoch
 AND NOT b.revoked AND b.end_sequence_exclusive>b.start_sequence
 AND l.published_sequence>=b.end_sequence_exclusive-1 AND jsonb_array_length(l.segments)>=b.end_sequence_exclusive))
AND NOT EXISTS(SELECT 1 FROM recording_deletions d WHERE d.recording_id=c.recording_id) AND NOT EXISTS(SELECT 1 FROM recording_packages WHERE state IN ('freezing','validating') AND validation_attempts<3 AND next_attempt_at<=now() AND (claimed_until IS NULL OR claimed_until<=now())) AND NOT EXISTS(SELECT 1 FROM recording_sources WHERE state IN ('finalizing','queued','processing') AND processing_attempts<3 AND retry_until>now() AND (claimed_until IS NULL OR claimed_until<=now())) ORDER BY c.created_at`

const previewWakeCandidate = `SELECT id FROM recording_packages WHERE NOT EXISTS(SELECT 1 FROM recording_live_previews lp WHERE lp.capture_id=recording_packages.id AND lp.claimed_until>now()) AND state='ready' AND media_expires_at>clock_timestamp() AND preview_state IN ('pending','processing') AND preview_attempts<3 AND preview_next_attempt_at<=clock_timestamp() AND (preview_claimed_until IS NULL OR preview_claimed_until<=clock_timestamp()) AND NOT EXISTS(SELECT 1 FROM recording_packages WHERE state IN ('freezing','validating') AND validation_attempts<3 AND next_attempt_at<=clock_timestamp() AND (claimed_until IS NULL OR claimed_until<=clock_timestamp())) AND NOT EXISTS(SELECT 1 FROM recording_sources WHERE state IN ('finalizing','queued','processing') AND processing_attempts<3 AND retry_until>clock_timestamp() AND (claimed_until IS NULL OR claimed_until<=clock_timestamp())) ORDER BY ready_at`

const livePreviewPending = `cap.state IN ('uploading','freezing','validating') AND NOT EXISTS(SELECT 1 FROM recording_packages vp WHERE vp.id=cap.package_id AND vp.state='ready') AND ` + livePreviewAlive

const livePreviewBootstrapCandidate = `SELECT l.capture_id FROM recording_live l JOIN recording_captures cap ON cap.id=l.capture_id WHERE l.published_sequence>=0 AND NOT EXISTS(SELECT 1 FROM recording_live_previews p WHERE p.capture_id=l.capture_id) AND ` + livePreviewPending + ` AND ` + previewWorkWaiting

const livePreviewWakeCandidate = `SELECT p.capture_id,p.completed_sequence,p.vtt,LEAST(l.published_sequence,p.completed_sequence+6),l.segments FROM recording_live_previews p JOIN recording_live l ON l.capture_id=p.capture_id JOIN recording_captures cap ON cap.id=p.capture_id WHERE p.completed_sequence<l.published_sequence AND p.next_attempt_at<=now() AND (p.claimed_until IS NULL OR p.claimed_until<=now()) AND ` + livePreviewPending + ` AND ` + previewWorkWaiting + ` ORDER BY p.next_attempt_at`
